              "C: odczytaj karty na stole.",
              "F: odczytaj kolor wyj\u015Bcia.",
              "T: sprawd\u017A, czyja jest tura.",
              "S: odczytaj wyniki zako\u0144czonych rozda\u0144.",
              "Shift+S: odczytaj punkty z zako\u0144czonych lew bie\u017C\u0105cego rozdania; talon liczy si\u0119 przy rozliczeniu.")
          ]
        when "ru"
          [
            rule_section(:play, "\u0420\u0430\u0437\u0434\u0430\u0447\u0430 \u0438 \u0442\u043E\u0440\u0433\u043E\u0432\u043B\u044F",
              "\u0418\u0433\u0440\u0430\u044E\u0442 \u0447\u0435\u0442\u044B\u0440\u0435 \u0447\u0435\u043B\u043E\u0432\u0435\u043A\u0430. \u041A\u0430\u0436\u0434\u044B\u0439 \u043F\u043E\u043B\u0443\u0447\u0430\u0435\u0442 18 \u043A\u0430\u0440\u0442, \u0435\u0449\u0451 \u0448\u0435\u0441\u0442\u044C \u043E\u0431\u0440\u0430\u0437\u0443\u044E\u0442 \u043F\u0440\u0438\u043A\u0443\u043F. \u041F\u043E\u0431\u0435\u0434\u0438\u0442\u0435\u043B\u044C \u0442\u043E\u0440\u0433\u043E\u0432\u043B\u0438 \u0441\u0442\u0430\u043D\u043E\u0432\u0438\u0442\u0441\u044F \u0440\u0430\u0437\u044B\u0433\u0440\u044B\u0432\u0430\u044E\u0449\u0438\u043C \u0438 \u0438\u0433\u0440\u0430\u0435\u0442 \u043F\u0440\u043E\u0442\u0438\u0432 \u043E\u0441\u0442\u0430\u043B\u044C\u043D\u044B\u0445 \u0442\u0440\u043E\u0438\u0445. \u041D\u0430\u0436\u043C\u0438\u0442\u0435 B, \u0432\u044B\u0431\u0435\u0440\u0438\u0442\u0435 \u0437\u0430\u044F\u0432\u043A\u0443 \u0441\u0442\u0440\u0435\u043B\u043A\u0430\u043C\u0438 \u0438 \u043F\u043E\u0434\u0442\u0432\u0435\u0440\u0434\u0438\u0442\u0435 Enter. \u041C\u043E\u0436\u043D\u043E \u0441\u043F\u0430\u0441\u043E\u0432\u0430\u0442\u044C \u0438\u043B\u0438 \u043D\u0430\u0437\u0432\u0430\u0442\u044C \u0431\u043E\u043B\u0435\u0435 \u0432\u044B\u0441\u043E\u043A\u0438\u0439 \u043A\u043E\u043D\u0442\u0440\u0430\u043A\u0442. \u0415\u0441\u043B\u0438 \u043F\u0430\u0441\u0443\u044E\u0442 \u0432\u0441\u0435, \u043A\u0430\u0440\u0442\u044B \u0441\u0434\u0430\u044E\u0442\u0441\u044F \u0437\u0430\u043D\u043E\u0432\u043E.",
              "\u041A\u043E\u043D\u0442\u0440\u0430\u043A\u0442\u044B \u043F\u043E \u0432\u043E\u0437\u0440\u0430\u0441\u0442\u0430\u043D\u0438\u044E: Petite, Garde, Garde sans \u0438 Garde contre. \u0412 Petite \u0438 Garde \u043F\u0440\u0438\u043A\u0443\u043F \u043F\u043E\u043A\u0430\u0437\u044B\u0432\u0430\u0435\u0442\u0441\u044F \u0432\u0441\u0435\u043C, \u0437\u0430\u0442\u0435\u043C \u0440\u0430\u0437\u044B\u0433\u0440\u044B\u0432\u0430\u044E\u0449\u0438\u0439 \u0431\u0435\u0440\u0451\u0442 \u0435\u0433\u043E \u0438 \u0441\u043D\u043E\u0441\u0438\u0442 \u0448\u0435\u0441\u0442\u044C \u043A\u0430\u0440\u0442. \u041A\u043E\u0440\u043E\u043B\u0435\u0439 \u0438 \u0442\u0440\u0438 \u0443\u0434\u043B\u0435\u0440\u0430 \u0441\u043D\u043E\u0441\u0438\u0442\u044C \u043D\u0435\u043B\u044C\u0437\u044F. \u041A\u043E\u0437\u044B\u0440\u0438 \u043C\u043E\u0436\u043D\u043E \u0441\u043D\u043E\u0441\u0438\u0442\u044C, \u0442\u043E\u043B\u044C\u043A\u043E \u0435\u0441\u043B\u0438 \u043F\u043E\u0434\u0445\u043E\u0434\u044F\u0449\u0438\u0445 \u043E\u0431\u044B\u0447\u043D\u044B\u0445 \u043A\u0430\u0440\u0442 \u0443\u0436\u0435 \u043D\u0435\u0442. \u0421\u043D\u043E\u0441 \u0438\u0434\u0451\u0442 \u0432 \u043E\u0447\u043A\u0438 \u0440\u0430\u0437\u044B\u0433\u0440\u044B\u0432\u0430\u044E\u0449\u0435\u0433\u043E. \u0412 Garde sans \u0435\u043C\u0443 \u0436\u0435 \u0437\u0430\u0441\u0447\u0438\u0442\u044B\u0432\u0430\u0435\u0442\u0441\u044F \u0437\u0430\u043A\u0440\u044B\u0442\u044B\u0439 \u043F\u0440\u0438\u043A\u0443\u043F, \u0430 \u0432 Garde contre \u043F\u0440\u0438\u043A\u0443\u043F \u0434\u043E\u0441\u0442\u0430\u0451\u0442\u0441\u044F \u0437\u0430\u0449\u0438\u0442\u0435."),
            rule_section(:trumps, "\u0420\u043E\u0437\u044B\u0433\u0440\u044B\u0448 \u0432\u0437\u044F\u0442\u043E\u043A",
              "\u0412\u044B\u0431\u0435\u0440\u0438\u0442\u0435 \u043A\u0430\u0440\u0442\u0443 \u0441\u0442\u0440\u0435\u043B\u043A\u0430\u043C\u0438 \u0438 \u0441\u044B\u0433\u0440\u0430\u0439\u0442\u0435 Enter. \u0412\u043E \u0432\u0437\u044F\u0442\u043A\u0443 \u043A\u0430\u0436\u0434\u044B\u0439 \u043A\u043B\u0430\u0434\u0451\u0442 \u043F\u043E \u043E\u0434\u043D\u043E\u0439 \u043A\u0430\u0440\u0442\u0435. \u041D\u0443\u0436\u043D\u043E \u043E\u0442\u0432\u0435\u0447\u0430\u0442\u044C \u0432 \u043C\u0430\u0441\u0442\u044C \u0437\u0430\u0445\u043E\u0434\u0430, \u0434\u0430\u0436\u0435 \u0435\u0441\u043B\u0438 \u043A\u0442\u043E-\u0442\u043E \u0443\u0436\u0435 \u043F\u043E\u043B\u043E\u0436\u0438\u043B \u043A\u043E\u0437\u044B\u0440\u044C. \u0415\u0441\u043B\u0438 \u043C\u0430\u0441\u0442\u0438 \u043D\u0435\u0442, \u043D\u0443\u0436\u043D\u043E \u0438\u0433\u0440\u0430\u0442\u044C \u043A\u043E\u0437\u044B\u0440\u0435\u043C. \u0421\u0442\u0430\u0440\u0448\u0438\u0439 \u043A\u043E\u0437\u044B\u0440\u044C \u043D\u0430 \u0441\u0442\u043E\u043B\u0435 \u043D\u0443\u0436\u043D\u043E \u043F\u0435\u0440\u0435\u0431\u0438\u0442\u044C, \u0435\u0441\u043B\u0438 \u0432\u043E\u0437\u043C\u043E\u0436\u043D\u043E; \u0438\u043D\u0430\u0447\u0435 \u043C\u043E\u0436\u043D\u043E \u043F\u043E\u043B\u043E\u0436\u0438\u0442\u044C \u043C\u043B\u0430\u0434\u0448\u0438\u0439. \u0415\u0441\u043B\u0438 \u043D\u0435\u0442 \u043D\u0438 \u043C\u0430\u0441\u0442\u0438, \u043D\u0438 \u043A\u043E\u0437\u044B\u0440\u0435\u0439, \u043C\u043E\u0436\u043D\u043E \u0438\u0433\u0440\u0430\u0442\u044C \u043B\u044E\u0431\u0443\u044E \u043A\u0430\u0440\u0442\u0443. \u041F\u043E\u0431\u0435\u0436\u0434\u0430\u0435\u0442 \u0441\u0442\u0430\u0440\u0448\u0438\u0439 \u043A\u043E\u0437\u044B\u0440\u044C, \u0430 \u0431\u0435\u0437 \u043A\u043E\u0437\u044B\u0440\u0435\u0439 \u2014 \u0441\u0442\u0430\u0440\u0448\u0430\u044F \u043A\u0430\u0440\u0442\u0430 \u043C\u0430\u0441\u0442\u0438 \u0437\u0430\u0445\u043E\u0434\u0430. \u041F\u043E\u0431\u0435\u0434\u0438\u0442\u0435\u043B\u044C \u0437\u0430\u0445\u043E\u0434\u0438\u0442 \u0441\u043B\u0435\u0434\u0443\u044E\u0449\u0438\u043C.",
              "\u0412 \u043A\u0430\u0436\u0434\u043E\u0439 \u043C\u0430\u0441\u0442\u0438 \u043F\u043E\u0440\u044F\u0434\u043E\u043A \u043E\u0442 \u0441\u0442\u0430\u0440\u0448\u0435\u0439 \u043A\u0430\u0440\u0442\u044B: \u043A\u043E\u0440\u043E\u043B\u044C, \u0434\u0430\u043C\u0430, \u0440\u044B\u0446\u0430\u0440\u044C, \u0432\u0430\u043B\u0435\u0442, \u0434\u0435\u0441\u044F\u0442\u043A\u0430 \u0438 \u0434\u0430\u043B\u0435\u0435 \u0434\u043E \u0442\u0443\u0437\u0430. \u041A\u043E\u0437\u044B\u0440\u044C 21 \u2014 \u0441\u0442\u0430\u0440\u0448\u0438\u0439, \u0430 \u043A\u043E\u0437\u044B\u0440\u044C 1, \u041C\u0430\u043B\u044B\u0439, \u2014 \u043C\u043B\u0430\u0434\u0448\u0438\u0439. \u041E\u0442\u0433\u043E\u0432\u043E\u0440\u043A\u0443 \u043C\u043E\u0436\u043D\u043E \u0441\u044B\u0433\u0440\u0430\u0442\u044C \u0432 \u043B\u044E\u0431\u043E\u0439 \u043C\u043E\u043C\u0435\u043D\u0442, \u043E\u043D\u0430 \u043D\u0435 \u0437\u0430\u0434\u0430\u0451\u0442 \u043C\u0430\u0441\u0442\u044C \u0437\u0430\u0445\u043E\u0434\u0430. \u0414\u043E \u043F\u043E\u0441\u043B\u0435\u0434\u043D\u0435\u0439 \u0432\u0437\u044F\u0442\u043A\u0438 \u043E\u043D\u0430 \u043E\u0441\u0442\u0430\u0451\u0442\u0441\u044F \u0443 \u0441\u0432\u043E\u0435\u0439 \u0441\u0442\u043E\u0440\u043E\u043D\u044B; \u0435\u0441\u043B\u0438 \u0432\u0437\u044F\u0442\u043A\u0443 \u0437\u0430\u0431\u0440\u0430\u043B\u0430 \u0434\u0440\u0443\u0433\u0430\u044F \u0441\u0442\u043E\u0440\u043E\u043D\u0430, \u0435\u0439 \u043F\u0435\u0440\u0435\u0434\u0430\u0451\u0442\u0441\u044F \u043F\u043E\u043B-\u043E\u0447\u043A\u0430. \u0412 \u043F\u043E\u0441\u043B\u0435\u0434\u043D\u0435\u0439 \u0432\u0437\u044F\u0442\u043A\u0435 \u041E\u0442\u0433\u043E\u0432\u043E\u0440\u043A\u0430 \u0434\u043E\u0441\u0442\u0430\u0451\u0442\u0441\u044F \u0435\u0451 \u043F\u043E\u0431\u0435\u0434\u0438\u0442\u0435\u043B\u044E."),
            rule_section(:scoring, "\u041F\u043E\u0434\u0441\u0447\u0451\u0442 \u043E\u0447\u043A\u043E\u0432 \u0438 \u043A\u043E\u043D\u0435\u0446 \u0438\u0433\u0440\u044B",
              "\u0422\u0440\u0438 \u0443\u0434\u043B\u0435\u0440\u0430 \u2014 \u043A\u043E\u0437\u044B\u0440\u044C 1, \u043A\u043E\u0437\u044B\u0440\u044C 21 \u0438 \u041E\u0442\u0433\u043E\u0432\u043E\u0440\u043A\u0430. \u041A\u0430\u0436\u0434\u044B\u0439 \u0441\u0442\u043E\u0438\u0442 4,5 \u043E\u0447\u043A\u0430, \u043A\u0430\u043A \u0438 \u043A\u043E\u0440\u043E\u043B\u044C. \u0414\u0430\u043C\u0430 \u0441\u0442\u043E\u0438\u0442 3,5, \u0440\u044B\u0446\u0430\u0440\u044C \u2014 2,5, \u0432\u0430\u043B\u0435\u0442 \u2014 1,5, \u043E\u0441\u0442\u0430\u043B\u044C\u043D\u044B\u0435 \u043A\u0430\u0440\u0442\u044B \u2014 \u043F\u043E \u043F\u043E\u043B-\u043E\u0447\u043A\u0430. \u041F\u043E\u0441\u043B\u0435 18 \u0432\u0437\u044F\u0442\u043E\u043A \u0440\u0430\u0437\u044B\u0433\u0440\u044B\u0432\u0430\u044E\u0449\u0435\u043C\u0443 \u043D\u0443\u0436\u043D\u043E 56 \u043E\u0447\u043A\u043E\u0432 \u0431\u0435\u0437 \u0443\u0434\u043B\u0435\u0440\u043E\u0432, 51 \u0441 \u043E\u0434\u043D\u0438\u043C, 41 \u0441 \u0434\u0432\u0443\u043C\u044F \u0438\u043B\u0438 36 \u0441 \u0442\u0440\u0435\u043C\u044F. \u041F\u0440\u0438\u043A\u0443\u043F \u0437\u0430\u0441\u0447\u0438\u0442\u044B\u0432\u0430\u0435\u0442\u0441\u044F \u0441\u0442\u043E\u0440\u043E\u043D\u0435, \u0443\u043A\u0430\u0437\u0430\u043D\u043D\u043E\u0439 \u043A\u043E\u043D\u0442\u0440\u0430\u043A\u0442\u043E\u043C.",
              "\u041A \u0430\u0431\u0441\u043E\u043B\u044E\u0442\u043D\u043E\u0439 \u0440\u0430\u0437\u043D\u0438\u0446\u0435 \u0441 \u043D\u0443\u0436\u043D\u044B\u043C \u0447\u0438\u0441\u043B\u043E\u043C \u043E\u0447\u043A\u043E\u0432 \u043F\u0440\u0438\u0431\u0430\u0432\u044C\u0442\u0435 25. \u0423\u043C\u043D\u043E\u0436\u044C\u0442\u0435 \u0440\u0435\u0437\u0443\u043B\u044C\u0442\u0430\u0442 \u043D\u0430 1 \u0434\u043B\u044F Petite, 2 \u0434\u043B\u044F Garde, 4 \u0434\u043B\u044F Garde sans \u0438\u043B\u0438 6 \u0434\u043B\u044F Garde contre. \u0415\u0441\u043B\u0438 \u043A\u043E\u043D\u0442\u0440\u0430\u043A\u0442 \u0432\u044B\u043F\u043E\u043B\u043D\u0435\u043D, \u043A\u0430\u0436\u0434\u044B\u0439 \u0437\u0430\u0449\u0438\u0442\u043D\u0438\u043A \u0442\u0435\u0440\u044F\u0435\u0442 \u044D\u0442\u0443 \u0441\u0443\u043C\u043C\u0443, \u0430 \u0440\u0430\u0437\u044B\u0433\u0440\u044B\u0432\u0430\u044E\u0449\u0438\u0439 \u043F\u043E\u043B\u0443\u0447\u0430\u0435\u0442 \u0432\u0442\u0440\u043E\u0435 \u0431\u043E\u043B\u044C\u0448\u0435. \u0415\u0441\u043B\u0438 \u043A\u043E\u043D\u0442\u0440\u0430\u043A\u0442 \u043F\u0440\u043E\u0438\u0433\u0440\u0430\u043D, \u0437\u043D\u0430\u043A\u0438 \u043C\u0435\u043D\u044F\u044E\u0442\u0441\u044F. \u041D\u0430\u043F\u0440\u0438\u043C\u0435\u0440, 44 \u043E\u0447\u043A\u0430 \u043F\u0440\u0438 \u043F\u043E\u0440\u043E\u0433\u0435 41 \u0432 Garde \u0434\u0430\u044E\u0442 \u043A\u0430\u0436\u0434\u043E\u043C\u0443 \u0437\u0430\u0449\u0438\u0442\u043D\u0438\u043A\u0443 \u043C\u0438\u043D\u0443\u0441 56, \u0430 \u0440\u0430\u0437\u044B\u0433\u0440\u044B\u0432\u0430\u044E\u0449\u0435\u043C\u0443 \u043F\u043B\u044E\u0441 168.",
              "\u041F\u043E \u0443\u043C\u043E\u043B\u0447\u0430\u043D\u0438\u044E \u0438\u0433\u0440\u0430 \u0437\u0430\u043A\u0430\u043D\u0447\u0438\u0432\u0430\u0435\u0442\u0441\u044F \u043F\u043E\u0441\u043B\u0435 \u043E\u0434\u043D\u043E\u0439 \u0441\u044B\u0433\u0440\u0430\u043D\u043D\u043E\u0439 \u0440\u0430\u0437\u0434\u0430\u0447\u0438. \u041F\u0440\u0438 \u0441\u043E\u0437\u0434\u0430\u043D\u0438\u0438 \u0441\u0442\u043E\u043B\u0430 \u043C\u043E\u0436\u043D\u043E \u0438\u0437\u043C\u0435\u043D\u0438\u0442\u044C \u0447\u0438\u0441\u043B\u043E \u0440\u0430\u0437\u0434\u0430\u0447 \u0438\u043B\u0438 \u0437\u0430\u0434\u0430\u0442\u044C \u043F\u0440\u0435\u0434\u0435\u043B \u043E\u0447\u043A\u043E\u0432; \u043D\u043E\u043B\u044C \u043E\u0442\u043A\u043B\u044E\u0447\u0430\u0435\u0442 \u0441\u043E\u043E\u0442\u0432\u0435\u0442\u0441\u0442\u0432\u0443\u044E\u0449\u0438\u0439 \u043F\u0440\u0435\u0434\u0435\u043B. \u0415\u0441\u043B\u0438 \u0432\u043A\u043B\u044E\u0447\u0435\u043D\u044B \u043E\u0431\u0430, \u0438\u0433\u0440\u0430 \u0437\u0430\u043A\u0430\u043D\u0447\u0438\u0432\u0430\u0435\u0442\u0441\u044F \u043F\u043E\u0441\u043B\u0435 \u0440\u0430\u0437\u0434\u0430\u0447\u0438, \u0432 \u043A\u043E\u0442\u043E\u0440\u043E\u0439 \u0434\u043E\u0441\u0442\u0438\u0433\u043D\u0443\u0442 \u043F\u0435\u0440\u0432\u044B\u0439 \u0438\u0437 \u043D\u0438\u0445. \u0420\u0430\u0437\u0434\u0430\u0447\u0438 \u0441\u043E \u0432\u0441\u0435\u043E\u0431\u0449\u0438\u043C \u043F\u0430\u0441\u043E\u043C \u043D\u0435 \u0441\u0447\u0438\u0442\u0430\u044E\u0442\u0441\u044F. \u041F\u043E\u0431\u0435\u0436\u0434\u0430\u0435\u0442 \u043D\u0430\u0438\u0431\u043E\u043B\u044C\u0448\u0430\u044F \u0441\u0443\u043C\u043C\u0430; \u043F\u0440\u0438 \u0440\u0430\u0432\u0435\u043D\u0441\u0442\u0432\u0435 \u043F\u043E\u0431\u0435\u0434\u0430 \u043E\u0431\u0449\u0430\u044F."),
            rule_section(:controls, "\u041A\u043B\u0430\u0432\u0438\u0430\u0442\u0443\u0440\u0430",
              "\u0421\u0442\u0440\u0435\u043B\u043A\u0438: \u0432\u044B\u0431\u0440\u0430\u0442\u044C \u0437\u0430\u044F\u0432\u043A\u0443 \u0438\u043B\u0438 \u043A\u0430\u0440\u0442\u0443.",
              "Enter: \u043F\u043E\u0434\u0442\u0432\u0435\u0440\u0434\u0438\u0442\u044C \u0437\u0430\u044F\u0432\u043A\u0443, \u0441\u044B\u0433\u0440\u0430\u0442\u044C \u043A\u0430\u0440\u0442\u0443 \u0438\u043B\u0438 \u043E\u0442\u043B\u043E\u0436\u0438\u0442\u044C \u0435\u0451 \u043F\u0440\u0438 \u0441\u043D\u043E\u0441\u0435.",
              "B: \u043E\u0442\u043A\u0440\u044B\u0442\u044C \u0441\u043F\u0438\u0441\u043E\u043A \u043A\u043E\u043D\u0442\u0440\u0430\u043A\u0442\u043E\u0432.",
              "Escape: \u0437\u0430\u043A\u0440\u044B\u0442\u044C \u0441\u043F\u0438\u0441\u043E\u043A \u043A\u043E\u043D\u0442\u0440\u0430\u043A\u0442\u043E\u0432.",
              "H: \u043F\u0440\u043E\u0447\u0438\u0442\u0430\u0442\u044C \u0441\u0432\u043E\u044E \u0440\u0443\u043A\u0443.",
              "C: \u043F\u0440\u043E\u0447\u0438\u0442\u0430\u0442\u044C \u043A\u0430\u0440\u0442\u044B \u043D\u0430 \u0441\u0442\u043E\u043B\u0435.",
              "F: \u043D\u0430\u0437\u0432\u0430\u0442\u044C \u043C\u0430\u0441\u0442\u044C \u0437\u0430\u0445\u043E\u0434\u0430.",
              "T: \u0443\u0437\u043D\u0430\u0442\u044C, \u0447\u0435\u0439 \u0445\u043E\u0434.",
              "S: \u043F\u0440\u043E\u0447\u0438\u0442\u0430\u0442\u044C \u043E\u0447\u043A\u0438 \u0437\u0430\u0432\u0435\u0440\u0448\u0451\u043D\u043D\u044B\u0445 \u0440\u0430\u0437\u0434\u0430\u0447.",
              "Shift+S: \u043F\u0440\u043E\u0447\u0438\u0442\u0430\u0442\u044C \u043E\u0447\u043A\u0438 \u0437\u0430\u0432\u0435\u0440\u0448\u0451\u043D\u043D\u044B\u0445 \u0432\u0437\u044F\u0442\u043E\u043A \u0442\u0435\u043A\u0443\u0449\u0435\u0439 \u0440\u0430\u0437\u0434\u0430\u0447\u0438; \u043F\u0440\u0438\u043A\u0443\u043F \u0441\u0447\u0438\u0442\u0430\u0435\u0442\u0441\u044F \u043F\u0440\u0438 \u043F\u043E\u0434\u0432\u0435\u0434\u0435\u043D\u0438\u0438 \u0438\u0442\u043E\u0433\u043E\u0432.")
          ]
